export function mediumOf(specId) {
  for (const m of MEDIA) for (const s of m.specs) if (s.id === specId) return m;
  return null;
}

export function specOf(specId) {
  for (const m of MEDIA) for (const s of m.specs) if (s.id === specId) return s;
  return null;
}

